  state:()=>state,preview:(text,context)=>R.previewLuma(state,text,context),enact:enactLuma,
  place:({text,context,blueprint})=>{startCreationPlacement(blueprint);placing.luma={text,context};},
  events:()=>state.luma.receipts,intentions:()=>state.luma.intentions,
  release:id=>{let result;if(!change(()=>{result=R.dismissLumaIntention(state,id);}))throw Error($('notice').textContent);return result;},
