 schema:R.Creation.SCHEMA,
 example:kind=>R.Creation.seed(kind),
 inspect:()=>({profile:R.PROFILE,materials:{...(rehearsal?rehearsal.original:state).pack},creationKinds:[...R.Creation.KINDS],invited:state.creation.grants.agent,instances:state.creation.instances.map(e=>({id:e.id,name:e.blueprint.name,kind:e.blueprint.kind,revision:e.blueprint.revision}))}),
 preview:raw=>R.Creation.compile(raw),
 propose:raw=>{if(rehearsal||!state.creation.grants.agent)throw Error('The human has not invited local blueprint proposals.');if(state.creation.proposals.length>=4)throw Error('Four proposals are awaiting review.');const b=R.Creation.compile(raw).blueprint;state.creation.proposals.push(b);notice('A local agent blueprint is ready for review in the Foundry shelf.');return {acceptedForReview:true,name:b.name,instanceCreated:false,materialsSpent:false};}
